function compute(inputs){
  const prior = Math.min(Math.max(inputs.prior, 0), 1);
  const sens = Math.min(Math.max(inputs.sens, 0), 1);
  const fpr = Math.min(Math.max(inputs.fpr, 0), 1);
  const N = 1000;
  const tp = sens * prior;
  const fp = fpr * (1 - prior);
  const denom = tp + fp;
  const posterior = denom > 0 ? tp / denom : 0;
  const nD = prior * N;
  const nNotD = (1 - prior) * N;
  const nTP = tp * N;
  const nFP = fp * N;
  const nPos = denom * N;
  const table = {
    columns: ["Quantity", "Symbol", "Value"],
    rows: [
      ["Prevalence", "P(D)", prior.toFixed(4)],
      ["Sensitivity", "P(+|D)", sens.toFixed(4)],
      ["False positive rate", "P(+|\u00acD)", fpr.toFixed(4)],
      ["Joint: disease & positive", "P(+|D)P(D)", tp.toFixed(6)],
      ["Joint: no disease & positive", "P(+|\u00acD)(1-P(D))", fp.toFixed(6)],
      ["Total positive", "P(+)", denom.toFixed(6)],
      ["Posterior", "P(D|+)", posterior.toFixed(6)],
      ["People with disease (of 1000)", "n_D", nD.toFixed(1)],
      ["True positives (of 1000)", "n_TP", nTP.toFixed(1)],
      ["False positives (of 1000)", "n_FP", nFP.toFixed(1)],
      ["All positives (of 1000)", "n_+", nPos.toFixed(1)]
    ]
  };
  const flow = {
    nodes: [
      {id: "pop", label: "1000 people", value: N},
      {id: "d", label: "Disease", value: nD},
      {id: "nd", label: "No disease", value: nNotD},
      {id: "tp", label: "True positive", value: nTP},
      {id: "fn", label: "False negative", value: nD - nTP},
      {id: "fp", label: "False positive", value: nFP},
      {id: "tn", label: "True negative", value: nNotD - nFP}
    ],
    edges: [
      {from: "pop", to: "d", label: "P(D)", value: nD},
      {from: "pop", to: "nd", label: "1-P(D)", value: nNotD},
      {from: "d", to: "tp", label: "P(+|D)", value: nTP},
      {from: "d", to: "fn", label: "1-P(+|D)", value: nD - nTP},
      {from: "nd", to: "fp", label: "P(+|\u00acD)", value: nFP},
      {from: "nd", to: "tn", label: "1-P(+|\u00acD)", value: nNotD - nFP}
    ]
  };
  const insight = "Posterior P(D|+) = " + posterior.toFixed(4) + ". With prevalence " + prior.toFixed(3) + ", the true-positive joint " + tp.toFixed(5) + " is compared against the false-positive joint " + fp.toFixed(5) + ". " + (posterior < 0.5 ? "Because the disease is rare, false positives outnumber true positives, so a positive test is more likely to be a false alarm." : "Because the disease is common enough, true positives dominate and the positive test is informative.");
  return {posterior: posterior, tp: tp, fp: fp, denom: denom, table: table, flow: flow, insight: insight};
}
